        drop(snapshot);
        let query = self.query_vector(&query, service).await?;
        let local_started = Instant::now();
        let snapshot = self.snapshot(&service_key(service))?;
        let total = match &request.repository_id {
            Some(id) => snapshot.totals.get(id).copied().unwrap_or(0),
            None => snapshot.totals.values().sum(),
        };
